# Expected values generated by test/scipy/gen_optimize_root.py (scipy 1.18.1).
# root() with the nonlinear solvers, broyden/anderson/mixing/newton_krylov,
# df-sane, fixed_point and line_search.
import numpy as np
from scipy.optimize import root, broyden1, broyden2, anderson, linearmixing, \
    excitingmixing, newton_krylov, fixed_point, line_search

def close(x, ref, rtol: float = 1e-7, atol: float = 1e-10) -> bool:
    a = np.asarray(x, float)
    r = np.asarray(ref, float)
    if a.size != r.size:
        print('size', a.size, r.size)
        return False
    ok = True
    for u, v in zip(a.flat, r.flat):
        if abs(u - v) > atol + rtol * abs(v):
            print('mismatch', u, v)
            ok = False
    return ok

def check(cond: bool, what: str):
    if not cond:
        print('TEST FAILED:', what)

def F(x):
    return np.array([x[0] + 0.5 * (x[0] - x[1]) ** 3 - 1.0, 0.5 * (x[1] - x[0]) ** 3 + x[1]])

def H(x):
    n = x.size
    y = np.empty(n)
    for i in range(n):
        l = x[i - 1] if i > 0 else 0.0
        r = x[i + 1] if i < n - 1 else 0.0
        y[i] = 3 * x[i] - l - r + 0.2 * x[i] ** 3 - 1.0
    return y

def negH(x):
    return -H(x)

def test_root_F():
    x0 = np.array([1.0, 1.0])
    C = [
        ('broyden1', [0.841163765681265, 0.15883608200670896], 11, 23),
        ('broyden2', [0.8411636636160916, 0.15883609917743666], 10, 22),
        ('anderson', [0.8411640420890311, 0.15883595332074238], 9, 15),
        ('diagbroyden', [0.8411649535548642, 0.15883786766425537], 14, 26),
        ('df-sane', [0.8411639019102778, 0.15883609808972224], 8, 9),
    ]
    for m, x, nit, nfev in C:
        r = root(F, x0, method=m)
        check(close(r.x, x, 1e-6, 1e-8), m + ' x')
        check(r.success, m + ' success')
        check(r.nit == nit, m + ' nit')
        check(r.nfev == nfev, m + ' nfev')

def test_root_H():
    h0 = np.zeros(6)
    C = [
        ('broyden1', [0.5776632437981621, 0.7715470424587889, 0.828837305187352, 0.8288373051873629, 0.7715470424587832, 0.5776632437981639], 16),
        ('broyden2', [0.5776672714730124, 0.7715495021863154, 0.8288381853868421, 0.8288381853868423, 0.7715495021863154, 0.5776672714730124], 9),
        ('anderson', [0.5776648180238111, 0.7715473670444595, 0.828835348464291, 0.82883534846429, 0.771547367044462, 0.5776648180238104], 10),
        ('diagbroyden', [0.5776645924765796, 0.771548821142435, 0.8288351403635005, 0.8288351403635007, 0.7715488211424348, 0.5776645924765796], 66),
        ('krylov', [0.5776651842726065, 0.7715484156998176, 0.8288371677683187, 0.828837167606052, 0.7715484157826095, 0.5776651842726065], 4),
        ('df-sane', [0.5776647875661667, 0.7715473208772805, 0.8288353267044327, 0.8288353267044328, 0.7715473208772804, 0.5776647875661668], 16),
    ]
    for m, x, nit in C:
        r = root(H, h0, method=m)
        check(close(r.x, x, 1e-6, 1e-8), m + ' x')
        check(r.nit == nit, m + ' nit')
    T = [
        ('broyden1', [0.5776647883827553, 0.771547321207063, 0.8288353261466718, 0.8288353261470374, 0.7715473212068255, 0.5776647883828534]),
        ('broyden2', [0.5776647883828047, 0.7715473212069447, 0.8288353261468531, 0.8288353261468558, 0.7715473212069439, 0.5776647883828048]),
        ('anderson', [0.5776647883822396, 0.7715473212052129, 0.8288353261445112, 0.8288353261445055, 0.7715473212052217, 0.5776647883822358]),
        ('krylov', [0.5776647883828043, 0.7715473212069441, 0.8288353261468546, 0.8288353261468547, 0.7715473212069442, 0.5776647883828043]),
    ]
    for m, x in T:
        r = root(H, h0, method=m, tol=1e-9)
        check(close(r.x, x, 1e-7, 1e-9), m + ' tol x')
    r = root(H, h0, method='broyden1', options={'line_search': 'none', 'maxiter': 3})
    check(not r.success and r.status == 2 and r.nit == 3, 'maxiter')
    r = root(H, h0, method='df-sane', options={'line_search': 'cheng'})
    check(close(r.x, [0.5776647875661667, 0.7715473208772805, 0.8288353267044327, 0.8288353267044328, 0.7715473208772804, 0.5776647875661668], 1e-6, 1e-8), 'cheng')
    check(r.nit == 16 and r.nfev == 17, 'cheng counts')

def test_functions():
    h0 = np.zeros(6)
    LM = [0.5776636737035735, 0.7715454985390306, 0.8288331744850633, 0.8288331744850633, 0.7715454985390306, 0.5776636737035735]
    check(close(linearmixing(negH, h0, alpha=0.3, maxiter=500), LM, 1e-6, 1e-8), 'linearmixing')
    EM = [0.5776632660740036, 0.7715463287731399, 0.8288345404783128, 0.828834540478313, 0.7715463287731399, 0.5776632660740039]
    check(close(excitingmixing(negH, h0, alpha=0.2, maxiter=500, line_search=None), EM, 1e-6, 1e-8), 'excitingmixing')
    NK = [0.5776651842726065, 0.7715484156998176, 0.8288371677683187, 0.828837167606052, 0.7715484157826095, 0.5776651842726065]
    check(close(newton_krylov(H, h0), NK, 1e-6, 1e-8), 'newton_krylov')
    check(close(newton_krylov(H, h0, method='gmres'), [0.5776651843060647, 0.771548415722265, 0.8288371676667641, 0.8288371676310379, 0.7715484157577613, 0.5776651842299214], 1e-6, 1e-8), 'nk gmres')
    check(close(newton_krylov(H, h0, method='bicgstab'), [0.5776652178567268, 0.7715484751233, 0.8288371803980653, 0.8288371803649058, 0.7715484751159957, 0.5776652178394674], 1e-6, 1e-8), 'nk bicgstab')
    check(close(newton_krylov(H, h0, method='tfqmr'), [0.5776651842893997, 0.7715484157173877, 0.8288371676563305, 0.8288371676541005, 0.7715484157235784, 0.5776651842442411], 1e-6, 1e-8), 'nk tfqmr')
    check(close(broyden1(H, h0, reduction_method='svd', max_rank=3), [0.5776646981246077, 0.7715479566856643, 0.8288360066875864, 0.8288360066875864, 0.7715479566856643, 0.5776646981246077], 1e-6, 1e-8), 'b1 svd')
    check(close(broyden1(H, h0, reduction_method='simple', max_rank=2), [0.5776646330364228, 0.7715484950930839, 0.8288351465187099, 0.8288351465187096, 0.7715484950930838, 0.5776646330364228], 1e-6, 1e-8), 'b1 simple')
    check(close(broyden1(H, h0, line_search='wolfe'), [0.5776647652706044, 0.7715473429998541, 0.8288353257879326, 0.8288353257879363, 0.7715473429998493, 0.5776647652706084], 1e-6, 1e-8), 'b1 wolfe')
    check(close(broyden1(H, h0, line_search=None), [0.5776633743053153, 0.7715481004470878, 0.8288358920432884, 0.8288358920433971, 0.7715481004469971, 0.5776633743053667], 1e-6, 1e-8), 'b1 nols')
    check(close(broyden2(H, h0), [0.5776672714730124, 0.7715495021863154, 0.8288381853868421, 0.8288381853868423, 0.7715495021863154, 0.5776672714730124], 1e-6, 1e-8), 'broyden2')
    check(close(anderson(H, h0), [0.5776648180238111, 0.7715473670444595, 0.828835348464291, 0.82883534846429, 0.771547367044462, 0.5776648180238104], 1e-6, 1e-8), 'anderson')

def fpf(x, a):
    return np.sqrt(a / (x + 3))

def cosf(x):
    return np.cos(x)

def qf(x):
    return x[0] ** 2 + 3 * x[1] ** 2

def qg(x):
    return np.array([2 * x[0], 6 * x[1]])

def test_fixed_point_ls():
    r = fixed_point(fpf, [1.2, 1.3], args=(np.array([10.0, 12.0]),))
    check(close(r, [1.4920333011718165, 1.6128878647175449], 1e-7, 1e-9), 'fixed_point')
    check(abs(fixed_point(cosf, 0.5) - 0.7390851332151607) < 1e-9, 'fp del2')
    check(abs(fixed_point(cosf, 0.5, method='iteration') - 0.7390851305068246) < 1e-9, 'fp iteration')
    xk = np.array([1.8, 1.7])
    pk = -qg(xk)
    a, fc, gc, nf, of, ns = line_search(qf, qg, xk, pk)
    check(abs(a - 0.17995570321151713) < 1e-10, 'ls alpha')
    check(abs(nf - 1.3825913621262456) < 1e-10, 'ls fval')
    check(abs(of - 11.91) < 1e-10, 'ls oldfval')
    check(close(ns, [2.30431894, -0.81328904], 1e-7, 1e-7), 'ls grad')

test_root_F()
test_root_H()
test_functions()
test_fixed_point_ls()
print('optimize root OK')
